import java.util.Scanner;

public class Main {

    // 判断矩阵是否满足条件的函数
    public static boolean checkMatrix(int[][] a, int n, int m) {
        // 枚举每个可以和右下角比较的位置
        for (int i = 0; i < n - 1; i++) {
            for (int j = 0; j < m - 1; j++) {
                if (a[i][j] != a[i + 1][j + 1]) {
                    return false;
                }
            }
        }
        return true;
    }

